// Copy-and-swap idiom signature
ClassName& operator=(ClassName other) {  // Pass by value (creates copy)
  swap(*this, other);                    // Swap contents
  return *this;                          // Return reference
}  // Destructor cleans up old data when 'other' goes out of scope

// Required swap function (friend or member)
friend void swap(ClassName& first, ClassName& second) noexcept {
  using std::swap;
  swap(first.member1, second.member1);
  swap(first.member2, second.member2);
}

// What happens internally:
// obj1 = obj2;
// 1. Copy constructor creates temporary from obj2
// 2. Swap obj1's contents with temporary
// 3. Temporary (holding obj1's old data) is destroyed

code_example:
#include <iostream>
#include <algorithm>
#include <cstring>

class String {
    char* data;
    size_t len;

public:
    String(const char* str = "") : len(strlen(str)) {
        data = new char[len + 1];
        strcpy(data, str);
        std::cout << "Constructed: " << data << "\n";
    }

    String(const String& other) : len(other.len) {
        data = new char[len + 1];
        strcpy(data, other.data);
        std::cout << "Copy constructed: " << data << "\n";
    }

    ~String() {
        std::cout << "Destroyed: " << data << "\n";
        delete[] data;
    }

    friend void swap(String& first, String& second) noexcept {
        using std::swap;
        swap(first.data, second.data);
        swap(first.len, second.len);
        std::cout << "Swapped\n";
    }

    String& operator=(String other) {
        std::cout << "Assignment operator called\n";
        swap(*this, other);
        return *this;
    }

    const char* c_str() const { return data; }
};

int main() {
    String s1("Hello");
    String s2("World");

    std::cout << "\n=== s1 = s2 ===\n";
    s1 = s2;

    std::cout << "\nResult:\n";
    std::cout << "s1: " << s1.c_str() << "\n";
    std::cout << "s2: " << s2.c_str() << "\n";

    std::cout << "\nProgram ending:\n";
    return 0;
}
